<?php $isEdit = isset($product['id']); $title = $isEdit ? 'Sửa sản phẩm' : 'Thêm sản phẩm'; require dirname(__DIR__, 2) . '/layout/header.php'; ?>
<section class="card"><h1><?= e($title) ?></h1><?php if ($errors): ?><div class="error"><ul><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form method="post" action="<?= $isEdit ? url('admin/products/update',['id'=>$product['id']]) : url('admin/products/store') ?>"><input type="hidden" name="csrf" value="<?= e(\App\Core\Auth::csrfToken()) ?>"><div class="row">
<p class="field"><label>Tên món</label><input name="name" required value="<?= e($product['name'] ?? '') ?>"></p><p class="field"><label>SKU</label><input name="product_code" required value="<?= e($product['product_code'] ?? '') ?>"></p>
<p class="field"><label>Danh mục</label><select name="category_id" required><option value="">-- Chọn --</option><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= ((int)($product['category_id']??0)===(int)$category['id'])?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></p>
<p class="field"><label>Giá gốc</label><input type="number" min="0" name="original_price" required value="<?= e((string)($product['original_price'] ?? 0)) ?>"></p><p class="field"><label>Giá bán</label><input type="number" min="0" name="sale_price" required value="<?= e((string)($product['sale_price'] ?? 0)) ?>"></p><p class="field"><label>Tồn kho</label><input type="number" min="0" name="stock_quantity" required value="<?= e((string)($product['stock_quantity'] ?? 0)) ?>"></p></div>
<p class="field"><label>Mô tả</label><textarea name="description"><?= e($product['description'] ?? '') ?></textarea></p><label><input type="checkbox" name="is_published" <?= !isset($product['is_published']) || $product['is_published'] ? 'checked' : '' ?>> Mở bán</label><p><button>Lưu sản phẩm</button> <a href="<?= url('admin/products') ?>">Quay lại</a></p></form></section>
